architecture.h4_f:
msg = CBOR{v:1, maandishi, jibu_kwa, imetumwa_saa}
ct = AES-GCM-256-Simba kwa njia fiche(k, nonce, ujumbe, aad=idadi_ya_chumba)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, maandishi, jibu_kwa?, thread_id?, inataja?, sent_at}
ct = AES-GCM-256-Simba kwa njia fiche(ufunguo_wa_chumba, nonce, pt, aad=hex(kitambulisho_cha_chumba))
waya = CBOR{
  v: 1,
  maandishi ya siri: hex(ct), // urefu tofauti
  nonce: hex(12 B),
  mtumaji_pseudo: hex(16 B),
  imetumwa_kwa: unix_ms
}

cryptoWire.h5_f:
nje = CBOR{
  nodi_chanzo: hex32,
  target_user: int64,
  maandishi_ya_siri_ya_ndani: baiti,
  inner_nonce: baiti,
  imetumwa_kwa: unix_ms
}
sig = Ed25519-Sign(source_priv, nje)
POST /shirikisho/toa { bahasha: nje, sig: hex64 }

auth.h1_f:
POST /api/authentication/register
  { jina la mtumiaji, nenosiri, x25519_public_key, display_name, simu?, barua pepe?, avatar_emoji }

Jibu la 201 Limeundwa:
  {tokeni_ya_ufikiaji, onyesha_token, kitambulisho_cha_mtumiaji, jina la mtumiaji, ... }

auth.h3_f:
Upakiaji_wa_tokeni wa ufikiaji:
  { ndogo: user_id, jti: device_id, typ: "access", exp: sasa + 15min }
refresh_token payload:
  { ndogo: user_id, jti: device_id, typ: "refresh", exp: now + 30d }

HS256-iliyotiwa saini na nodi ya siri ya 64-byte kutoka .env

auth.h4_f:
register_begin(): changamoto = rand(32)
                    chaguzi = {rp.id, user.id, pubKeyCredParams, challenge }
                    chaguzi za kurudi

register_finish(uthibitisho):
  thibitisha uthibitisho dhidi ya TPM / Salama mizizi ya Enclave CA
  hifadhi { kitambulisho_cha_kitambulisho, ufunguo_wa_umma, kaunta: 0}

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60}
QR payload = { nonce, user_id, server: "https://node.example" }

POST /api/uthibitishaji/qr/thibitisha { nonce }
  → kifaa kipya kilichosajiliwa; JWTs walirudi.

rooms.h6_f:
mtumaji_pseudo = HMAC-SHA256(chumvi_ya_pseudo_chumba, kitambulisho_cha_ mtumaji)[:16] // 32 hex
ciphertext = AES-GCM-Simba kwa njia fiche(ufunguo_wa_chumba, nonce, CBOR_payload, aad=idadi_ya_chumba)

Fremu ya shabiki: { type:"m", chumba, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {filename, size, chunk_size_hint}
            ← {kitambulisho_cha_pakia, ukubwa_wa_chunk}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
kamilisha POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL kwa kutokamilika: 24 h

files.h4_f:
deny_list = {
  "maombi/x-dozi",
  "programu/x-sharedlib",
  "maombi/x-mach-binary",
}
ikiwa magic.from_buffer(buf[:1024]) kwenye deny_list: rudisha 415

presence.h1_f:
mteja: kwa kubofya kitufe cha kwanza → tuma {aina:"t", hali:"anza"}
         hakuna tena kutuma kwa 3 s isipokuwa mabadiliko ya hali
         Sekunde 10 baada ya kubofya kitufe cha mwisho → tuma {aina:"t", hali:"acha"}
kipokeaji: simama kiotomatiki sekunde 10 baada ya "kuanza" mara ya mwisho ikiwa hakuna "kuacha" iliyofika

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS tangaza {aina:"c", aina:"invite", call_id}
WS tangaza {aina:"c", aina:"ofa", sdp}
WS tangaza {aina:"c", aina:"jibu", sdp}
WS tangaza {aina:"c", aina:"mtahiniwa", barafu} × N
POST /api/calls/{call_id}/end

federation.h2_f:
bahasha = {
  nodi_chanzo : hex32,
  target_user : int64,
  maandishi_ya_siri_ya_ndani: baiti,
  inner_nonce : baiti,
  imetumwa_kwa : unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(bahasha))
POST /shirikisho/toa { bahasha, sig }

gossip.h3_f:
tangazo = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(tangazo))
upakiaji wa uvumi: [..., {ad, sig}, ...]

mpokeaji: thibitisha sig dhidi ya ad.pubkey → hifadhi ikiwa ni sawa
ziada: PoW ya 2^18 sufuri inayoongoza kwenye {pubkey, endpoint}

stealth.h2_f:
ClientHello byte = chrome_120_template na {
  nasibu = nasibu yetu,
  server_name = jina la mwenyeji wetu (au ECH-imefungwa),
  session_id = kitambulisho chetu cha kikao,
}
JA4 = t13d_xxxx_xxxx_xxxx (inalingana na uthabiti wa sasa wa Chrome)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {jina: x.vortexx.sol}
ECH: ClientHello.viendelezi += encrypted_sni(public_key_from_HTTPS_record)
DGA: kikoa(t) = base32( SHA256(mbegu ∥ YYYY-MM-DD) )[:16] + ".mfano"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Wavuti SW: self.addEventListener('push', e => decrypt(e.data))

